#### 2 · Destinos lógicos y la excepción loopback — decisión de diseño (CA-4, CA-5, CA-6)

**El problema real:** los destinos de QA son locales (`http://localhost:3200` para el dashboard — constante repetida en `agent-chat-handler.js:106`, `ops-restart-gate.js:21`, `human-block.js:657`, `commander-deterministic.js:1979`), y `ssrf-guard.validateHostname()` rechaza `localhost` de forma explícita (`ssrf-guard.js:221-223`) y RFC1918/loopback vía `BLOCKED_IPV4_CIDRS`. `http-client.request()` invoca ese guard incondicionalmente en L215 — por eso `http-client.test.js:100-110` tiene que **monkey-patchear `require.cache`** para poder testear contra `127.0.0.1`.

**Decisión: dos caminos separados, ninguno relaja el guard global.**

```js
// A) Destino REMOTO (público) → http-client con guard completo. Sin cambios.
const httpClient = require('./http-client');
const res = await httpClient.request(url, {
    method, headers, timeout: limites.timeout_total_ms,
    maxResponseBytes: limites.max_response_bytes,
    followRedirects: false,        // default de constants.js (FOLLOW_REDIRECTS_DEFAULT)
});

// B) Destino LOCAL allowlisteado → cliente mínimo interno, SIN redirects nunca.
```

`resolveDestino` es el único punto que traduce `destino_id` → endpoint, y **solo** desde config:

```js
function resolveDestino(destinoId, cfg) {
    const tabla = (cfg && cfg.qa_verifiers && cfg.qa_verifiers.destinos) || {};
    if (!Object.prototype.hasOwnProperty.call(tabla, destinoId)) {
        throw qaError('DESTINO_DESCONOCIDO',
            `destino_id '${destinoId}' no está en la allowlist de config.yaml ` +
            `(destinos válidos: ${Object.keys(tabla).join(', ')}). ` +
            `Agregarlo a qa_verifiers.destinos o corregir el criterio.`);   // CA-UX-4/CA-UX-5
    }
    const d = tabla[destinoId];
    return Object.freeze({ id: destinoId, protocol: d.protocol, host: d.host,
                           port: d.port, basePath: d.base_path || '', local: !!d.local });
}
```

- **No existe** un parámetro `url`, `host`, `port` ni `scheme` en ningún schema del catálogo. Si el criterio los trae, ajv los rechaza por `additionalProperties: false` — **no se normalizan, se rechazan** (CA-4).
- La URL final se arma como `protocol + host + port + basePath + path`, con `path` ya validado por regex (sin `..`, sin `@`, sin CRLF, sin esquema).

Cliente local mínimo — la clave es que **no puede seguir redirects porque no implementa redirects**:

```js
const net = require('node:net');
const http = require('node:http');

async function localRequest(destino, path, { method, headers, timeoutMs, maxBytes }) {
    // El host local DEBE ser IP literal o 'localhost': así no hay resolución DNS
    // atacable → DNS rebinding queda descartado por construcción en este camino.
    if (!net.isIP(destino.host) && destino.host !== 'localhost') {
        throw qaError('DESTINO_LOCAL_INVALIDO',
            `el destino local '${destino.id}' debe declarar IP literal o 'localhost' en config.yaml`);
    }
    const lookup = (h, o, cb) => cb(null, '127.0.0.1', 4);   // pin explícito
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(qaError('TIMEOUT', `timeout ${timeoutMs}ms`)), timeoutMs);
    try {
        const res = await sendOnce({ host: destino.host, port: destino.port, path, method,
                                     headers, signal: ac.signal,
                                     lookup: destino.host === 'localhost' ? lookup : undefined });
        if (res.statusCode >= 300 && res.statusCode < 400) {
            // CA-6: el salto NO se sigue. El Location NO se resuelve ni se loguea crudo.
            throw qaError('REDIRECT_BLOQUEADO',
                `el destino '${destino.id}' respondió ${res.statusCode} (redirect). ` +
                `Los verificadores no siguen redirects. Verificar que el servicio local esté sano.`);
        }
        return res;   // body cortado a maxBytes con marcador de truncado (CA-UX-3)
    } finally {
        clearTimeout(timer);
        ac.abort();   // el corte cancela el socket de verdad (CA-7), no solo reporta
    }
}
```

**Por qué NO se agrega una opción a `http-client.request`:** cualquier flag ahí (`allowPrivate`, `localDestination`) queda disponible para los ~30 callers del pipeline y convierte al guard en decorativo — exactamente lo que CA-5 prohíbe. El costo es ~80 líneas de cliente local deliberadamente pobre (sin retry, sin proxy, sin redirects, sin TLS), y ese empobrecimiento **es** la mitigación.

#### 3 · Límites y concurrencia (CA-7, CA-8, T3)

Perfil por verificador desde config, siempre más restrictivo que los defaults globales (`constants.js`: `TIMEOUT_TOTAL_DEFAULT_MS=60000`, `MAX_RESPONSE_BODY_BYTES_DEFAULT=10MB`). El semáforo es **la única pieza sin helper previo** en `.pipeline/lib/` (verificado: no hay `semaph|concurr|pool`):

```js
function createSemaphore(limit, maxQueue) {
    let active = 0; const queue = [];
    return {
        async acquire() {
            if (active >= limit) {
                if (queue.length >= maxQueue) {
                    throw qaError('CONCURRENCIA_EXCEDIDA',
                        `límite de ${limit} verificaciones simultáneas alcanzado y la cola está llena ` +
                        `(${maxQueue}). La ejecución se rechaza; reintentar cuando baje la carga.`);
                }
                await new Promise((r) => queue.push(r));
            }
            active += 1;
        },
        release() { active -= 1; const n = queue.shift(); if (n) n(); },
        stats() { return { active, pending: queue.length }; },
    };
}
```

- Semáforo **global** a nivel módulo (construido en el primer `run()` desde config) + límite **por invocación** cuando el caller pasa un lote.
- Default fail-closed: si `qa_verifiers.limites.max_concurrentes` no está en config, el schema estricto lo hace fallar al inicializar (CA-15) — no hay default silencioso alto.
- Exceder → rechazo **auditado** con `estado: no-verificable`, nunca ejecución silenciosa.

#### 4 · Auditoría redactada y salida legible (CA-9, CA-UX-3, T4)

```js
const { redactObject, redactUrlLike, redactStack, redactHeaders } = require('./redact');
const fs = require('node:fs');

function auditar(record) {
    const safe = redactObject({                      // cubre claves conocidas + match por valor
        ...record,
        url: redactUrlLike(record.url),
        request_headers: redactHeaders(record.request_headers || {}),
        error: record.error ? redactStack(record.error) : null,
    });
    fs.appendFileSync(AUDIT_PATH, JSON.stringify(safe) + '\n', 'utf8');  // modo 'a', append-only
}
```

- **Nunca** se persiste el body completo de la respuesta: solo `salida_observada` ya truncada + redactada.
- Truncado con marcador visible: `… truncado 4096 de 120340 bytes` (CA-UX-3) — jamás corte silencioso.
- Redacción **visible**: `authorization: ***`, no borrado de la clave — el operador tiene que saber que el header estaba.
- El cuerpo del mensaje arranca por *qué se esperaba vs. qué se observó*; el stack va después y redactado.

